window.irParaNacao = function(event, id) {
    if (event.target.closest('.admin-card-controls')) return;
    window.location.href = `nacao.html?id=${id}`;
};

const higienizarCaminho = (idElemento) => {
    const input = document.getElementById(idElemento);
    if (!input) return;
    input.addEventListener("input", function() {
        let valor = this.value.replace(/"/g, '').replace(/\\/g, '/');
        const indexMarcador = valor.indexOf('WT - Artes');
        if (indexMarcador !== -1) valor = valor.substring(indexMarcador);
        this.value = valor;
    });
};

const formatarTextoTatico = (texto) => {
    if (!texto) return "";
    let formatado = texto.replace(/\*\*(.*?)\*\*/g, '<strong style="color: #F2B400;">$1</strong>');
    return formatado.replace(/\n/g, '<br>');
};

