// ==========================================
// ABA TÁTICA (TOGGLE DO MENU)
// ==========================================
function ativarAbaTatica() {
    const navbar = document.querySelector('.top-navbar');
    const pullTab = document.getElementById('navPullTab');
    const pullIcon = document.getElementById('pullTabIcon');
    
    if (!navbar || !pullTab) return;

    // Define o espaço inicial do topo da página
    document.body.style.paddingTop = navbar.offsetHeight + 'px';

    pullTab.addEventListener('click', () => {
        navbar.classList.toggle('collapsed');
        if (navbar.classList.contains('collapsed')) {
            pullIcon.textContent = 'keyboard_double_arrow_down';
            document.body.style.paddingTop = '30px'; // A página desliza para cima e ocupa a tela
        } else {
            pullIcon.textContent = 'keyboard_double_arrow_up';
            document.body.style.paddingTop = navbar.offsetHeight + 'px'; // A página desce para o menu aparecer
        }
    });
}

function ativarRadarPesquisa(prefixoUrl) {
    const searchInput = document.getElementById('searchInput');
    if(!searchInput) return;

    const dropdown = document.createElement('div');
    dropdown.id = "radarResultados";
    dropdown.className = "search-suggestions";
    searchInput.parentElement.style.position = "relative";
    searchInput.parentElement.appendChild(dropdown);

    let timerBloqueio;

    searchInput.addEventListener("input", (e) => {
        const termo = e.target.value.trim();
        clearTimeout(timerBloqueio);
        
        if(termo.length < 2) { dropdown.style.display = "none"; return; }

        timerBloqueio = setTimeout(async () => {
            try {
                const resposta = await fetch(`${prefixoUrl}php/api/buscar_tanques.php?q=${encodeURIComponent(termo)}`);
                const json = await resposta.json();

                if(json.status === "success" && json.resultados.length > 0) {
                    dropdown.innerHTML = "";
                    json.resultados.forEach(tanque => {
                        dropdown.innerHTML += `
                            <a href="${prefixoUrl}ficha.html?id=${tanque.id}" class="suggestion-link" style="padding: 12px; border-bottom: 1px solid #333; transition: background 0.2s;" onmouseover="this.style.background='#222'" onmouseout="this.style.background='transparent'">
                                <img src="${prefixoUrl}${tanque.caminho_imagem}?v=${new Date().getTime()}" alt="${tanque.nome}" class="suggestion-icon" onerror="this.src='${prefixoUrl}WT - Artes/WT-ICO2.ico'">
                                <div style="display: flex; flex-direction: column;">
                                    <span style="font-weight: bold; font-size: 13px; color: #F2B400;">${tanque.nome}</span>
                                    <span style="font-size: 10px; color: #aaa;">${tanque.classe_veiculo || 'Tanque'} | ${tanque.nivel || '?'}</span>
                                </div>
                            </a>
                        `;
                    });
                    dropdown.style.display = "block";
                } else {
                    dropdown.innerHTML = `<div style="padding: 15px; color: #ff4d4d; font-size: 12px; text-align: center; font-family: monospace;">Nenhum alvo detetado.</div>`;
                    dropdown.style.display = "block";
                }
            } catch(err) {}
        }, 300);
    });

    document.addEventListener("click", (e) => { if(!searchInput.contains(e.target) && !dropdown.contains(e.target)) dropdown.style.display = "none"; });
}

function iniciarRelogio() {
    let elH = document.getElementById("warHours"), elM = document.getElementById("warMinutes"), elS = document.getElementById("warSeconds"), elD = document.getElementById("warClockDate");
    if (!(elH && elM && elS && elD)) return;
    const meses = ["JAN", "FEV", "MAR", "ABR", "MAI", "JUN", "JUL", "AGO", "SET", "OUT", "NOV", "DEZ"];
    const atualizarTempo = () => {
        let agora = new Date();
        elH.textContent = String(agora.getHours()).padStart(2, "0");
        elM.textContent = String(agora.getMinutes()).padStart(2, "0");
        elS.textContent = String(agora.getSeconds()).padStart(2, "0");
        elD.textContent = `${String(agora.getDate()).padStart(2, "0")} ${meses[agora.getMonth()]} ${agora.getFullYear()}`;
    };
    atualizarTempo(); setInterval(atualizarTempo, 1000);
}

// ==========================================
// MÓDULOS DE AUTENTICAÇÃO E SESSÃO
// ==========================================
function renderizarPlacaNacaoTopo(siglaNacao) {
    const badge = document.getElementById("userNationBadge");
    const cfg = NACOES_CONFIG[siglaNacao] || NACOES_CONFIG.USA;
    if (!badge) return;
    badge.style.borderColor = cfg.corBorda;
    badge.style.boxShadow = `0 0 10px ${cfg.glow}`;
    badge.innerHTML = `
        <div style="display:flex;align-items:center;gap:6px;">${cfg.svg}<span style="font-weight:bold;color:#fff;font-size:11px;">${cfg.sigla}</span></div>
        <span style="font-size:9px;color:#aaa;">${cfg.nome}</span><span style="font-size:8px;color:#F2B400;margin-left:2px;">▼</span>
    `;
}

function iniciarLogin(prefixoUrl) {
    let modalLogin = document.getElementById("loginModal");
    let btnAbreModal = document.querySelector(".btn-login");
    let btnFechaModal = document.getElementById("closeModal");
    let formularioLogin = document.getElementById("loginForm");
    if (!modalLogin || !formularioLogin) return;

    let inputEmail = document.getElementById("userEmail");
    let inputSenha = document.getElementById("userPassword");
    let btnAutenticar = document.getElementById("btnSubmitLogin");

    window.atualizarControlesInterface = function (isAuth, perfilUsuario) {
        const autenticado = isAuth === true || isAuth === "true";
        const ehAdmin = autenticado && (perfilUsuario || "").toLowerCase() === "admin";
        document.querySelectorAll(".admin-controls").forEach(el => el.style.display = ehAdmin ? "flex" : "none");
        const placaNacao = document.getElementById("userNationBadgeContainer");
        if (placaNacao) {
            placaNacao.style.display = autenticado ? "flex" : "none";
            if (autenticado) renderizarPlacaNacaoTopo(localStorage.getItem("userNation") || "USA");
        }
    };

    const validarInputs = () => {
        let ok = inputEmail.value.includes("@") && inputSenha.value.length > 0;
        btnAutenticar.disabled = !ok; btnAutenticar.classList.toggle("valido", ok);
    };

    if (btnAbreModal) btnAbreModal.addEventListener("click", async (e) => {
        e.preventDefault();
        if (localStorage.getItem("isAuth") === "true") {
            try {
                await fetch(`${prefixoUrl}php/api/logout.php`);
                localStorage.clear();
                window.location.reload();
            } catch (err) {}
        } else modalLogin.classList.add("ativo");
    });

    if (btnFechaModal) btnFechaModal.addEventListener("click", () => modalLogin.classList.remove("ativo"));
    inputEmail.addEventListener("input", validarInputs);
    inputSenha.addEventListener("input", validarInputs);

    formularioLogin.addEventListener("submit", async (e) => {
        e.preventDefault();
        btnAutenticar.disabled = true; btnAutenticar.innerHTML = "AUTENTICANDO...";
        try {
            let fd = new FormData(); fd.append("email", inputEmail.value); fd.append("senha", inputSenha.value);
            const res = await fetch(`${prefixoUrl}php/api/auth.php`, { method: "POST", body: fd });
            const json = await res.json();
            if (res.ok && json.status === "success") {
                localStorage.setItem("isAuth", "true"); localStorage.setItem("userRole", json.perfil);
                localStorage.setItem("userNickname", json.nickname); localStorage.setItem("userNation", json.nacao_favorita || "USA");
                window.location.reload();
            } else {
                document.getElementById("loginFeedback").textContent = json.message; document.getElementById("loginFeedback").style.display = "block";
                btnAutenticar.innerHTML = "FALHA"; setTimeout(() => { btnAutenticar.innerHTML = "AUTENTICAR"; btnAutenticar.disabled = false; }, 2000);
            }
        } catch (erro) {
            btnAutenticar.innerHTML = "AUTENTICAR"; btnAutenticar.disabled = false;
        }
    });

    (function verificarSessaoInicial() {
        let isAuth = localStorage.getItem("isAuth") === "true";
        let perfilUsuario = localStorage.getItem("userRole") || "visitante";
        if(document.getElementById("navLoginText")) document.getElementById("navLoginText").textContent = isAuth ? "SAIR" : "ENTRAR";
        atualizarControlesInterface(isAuth, perfilUsuario);
    })();
}

