// ==========================================
// MÓDULO CRUD: QUARTEL GENERAL (INDEX.HTML)
// ==========================================
function iniciarIndex(prefixoUrl) {
    const carrossel = document.getElementById("nacoesCarrossel");
    if (!carrossel) return;

    const btnNovaNacao = document.getElementById("btnNovaNacao");
    const modalNacao = document.getElementById("modalGerenciarNacao");
    const btnCancelar = document.getElementById("btnCancelarEdicao");
    const btnFecharX = document.getElementById("closeNacaoModalX");
    const perfilLocal = (localStorage.getItem("userRole") || "").toLowerCase();

    let nacoesData = [];

    const carregarNacoes = async () => {
        try {
            const resposta = await fetch(`${prefixoUrl}php/api/listar_nacoes.php`);
            const json = await resposta.json();

            if (json.status === "success") {
                nacoesData = json.nacoes;
                carrossel.innerHTML = "";
                if(document.getElementById("contadorNacoes")) document.getElementById("contadorNacoes").textContent = `${nacoesData.length} NAÇÕES`;

                nacoesData.forEach(nacao => {
                    let adminHTML = "";
                    if (perfilLocal === "admin") {
                        adminHTML = `
                            <div class="admin-card-controls">
                                <button class="btn-admin-card btn-editar-nacao" data-id="${nacao.Id}" style="background: #F2B400; color: #000;"><span class="material-symbols-outlined" style="font-size: 16px;">edit</span></button>
                                <button class="btn-admin-card btn-excluir-nacao" data-id="${nacao.Id}" style="background: var(--rus-vermelho); color: #fff;"><span class="material-symbols-outlined" style="font-size: 16px;">delete</span></button>
                            </div>
                        `;
                    }
                    // Mescla Tática: Mantém a silhueta, mas isola a cor forte da bandeira
                    carrossel.innerHTML += `
                        <div class="nation-card nation-bg card-custom-${nacao.Id}" onclick="irParaNacao(event, ${nacao.Id})" 
                             style="background-color: #555555; background-image: url('${prefixoUrl}${nacao.caminho_bandeira}?v=${new Date().getTime()}'); background-size: cover; background-position: center; background-blend-mode: multiply; border-color: ${nacao.cor_hex};">
                            
                            ${adminHTML}
                            
                            <h1 class="nation-title" style="text-shadow: 2px 2px 5px #000;">${nacao.nome.toUpperCase()}</h1>
                            
                            <img class="tank-silhueta" src="${prefixoUrl}${nacao.icone_silhueta || 'WT - Artes/WT-ICO2.ico'}?v=${new Date().getTime()}" alt="Silhueta de ${nacao.nome}" onerror="this.src='${prefixoUrl}WT - Artes/WT-ICO2.ico'">
                            
                            <div class="card-info-box" style="border-top: 2px solid ${nacao.cor_hex}; box-shadow: inset 0 2px 4px rgba(0, 0, 0, 0.5);">
                                <p>"${nacao.resumo_card || 'Força Militar em estruturação.'}"</p>
                            </div>

                        </div>
                    `;
                });
                vincularBotoesAdminIndex();
            }
        } catch (e) {}
    };

    const vincularBotoesAdminIndex = () => {
        document.querySelectorAll(".btn-editar-nacao").forEach(btn => {
            btn.addEventListener("click", (e) => {
                const id = e.currentTarget.getAttribute("data-id");
                const nacao = nacoesData.find(n => n.Id == id);
                document.getElementById("nacaoId").value = nacao.Id;
                document.getElementById("nacaoNome").value = nacao.nome;
                document.getElementById("nacaoCor").value = nacao.cor_hex;
                document.getElementById("nacaoBandeira").value = nacao.caminho_bandeira || "";
                document.getElementById("nacaoSilhueta").value = nacao.icone_silhueta || "";
                document.getElementById("nacaoResumo").value = nacao.resumo_card || "";
                document.getElementById("tituloModalNacao").textContent = "EDITAR DADOS DA NAÇÃO";
                modalNacao.classList.add("ativo");
            });
        });

        document.querySelectorAll(".btn-excluir-nacao").forEach(btn => {
            btn.addEventListener("click", async (e) => {
                const id = e.currentTarget.getAttribute("data-id");
                const nacao = nacoesData.find(n => n.Id == id);
                if(confirm(`ALERTA SEVERO:\nDeletar a nação "${nacao.nome}" destruirá todos os tanques associados a ela.\nProsseguir com a obliteração?`)) {
                    let fd = new FormData(); fd.append("acao", "excluir_nacao"); fd.append("id", id);
                    const res = await fetch(`${prefixoUrl}php/api/admin_index_api.php`, { method: "POST", body: fd });
                    if (res.ok) window.location.reload();
                }
            });
        });
    };

    const fecharModal = () => modalNacao.classList.remove("ativo");
    if (btnFecharX) btnFecharX.addEventListener("click", fecharModal);
    if (btnCancelar) btnCancelar.addEventListener("click", fecharModal);

    if (perfilLocal === "admin" && btnNovaNacao) {
        btnNovaNacao.style.display = "block";
        btnNovaNacao.addEventListener("click", () => {
            document.getElementById("formGerenciarNacao").reset();
            document.getElementById("nacaoId").value = "";
            document.getElementById("tituloModalNacao").textContent = "FUNDAR NOVA NAÇÃO";
            modalNacao.classList.add("ativo");
        });

        higienizarCaminho("nacaoBandeira"); higienizarCaminho("nacaoSilhueta");

        document.getElementById("formGerenciarNacao").addEventListener("submit", async (e) => {
            e.preventDefault();
            const btnSalvar = document.getElementById("btnSalvarNacao");
            btnSalvar.disabled = true; btnSalvar.innerHTML = "PROCESSANDO...";
            let fd = new FormData();
            fd.append("acao", "salvar_nacao");
            fd.append("id", document.getElementById("nacaoId").value); 
            fd.append("nome", document.getElementById("nacaoNome").value);
            fd.append("cor", document.getElementById("nacaoCor").value);
            fd.append("bandeira", document.getElementById("nacaoBandeira").value);
            fd.append("silhueta", document.getElementById("nacaoSilhueta").value);
            fd.append("resumo", document.getElementById("nacaoResumo").value);
            
            try {
                const res = await fetch(`${prefixoUrl}php/api/admin_index_api.php`, { method: "POST", body: fd });
                const json_res = await res.json();
                if (res.ok && json_res.status === "success") window.location.reload();
                else { alert("Erro: " + json_res.message); btnSalvar.disabled = false; btnSalvar.innerHTML = "SALVAR NAÇÃO"; }
            } catch(err) { btnSalvar.disabled = false; btnSalvar.innerHTML = "SALVAR NAÇÃO"; }
        });
    }
    carregarNacoes();
}

// ==========================================
// MÓDULO CRUD: DOUTRINA NACIONAL (NACAO.HTML)
// ==========================================
function iniciarNacao(prefixoUrl) {
    const container = document.getElementById("nacaoContainer");
    if (!container) return;

    const urlParams = new URLSearchParams(window.location.search);
    const nacaoId = urlParams.get('id');
    const overlay = document.getElementById("loadingOverlay");
    const listaTanques = document.getElementById("listaTanques");
    const btnEditarNacao = document.getElementById("btnEditarNacao");
    const btnNovoTanque = document.getElementById("btnNovoTanque");
    const modalNacao = document.getElementById("edicaoNacaoModal");
    const perfilLocal = (localStorage.getItem("userRole") || "").toLowerCase();

    if (!nacaoId) { if(overlay) overlay.innerHTML = "<span style='color:red;'>Nação não identificada.</span>"; return; }

    const carregarDadosNacao = async () => {
        try {
            const resposta = await fetch(`${prefixoUrl}php/api/listar_frota_nacao.php?nacao_id=${nacaoId}`);
            const json = await resposta.json();

            if (json.status === "success") {
                const nacao = json.nacao;
                const frota = json.tanques;

                document.title = `${nacao.nome.toUpperCase()} - War Thunder`;
                document.getElementById("dinNomeNacao").textContent = nacao.nome.toUpperCase();
                document.getElementById("dinBandeira").src = `${prefixoUrl}${nacao.caminho_bandeira || ""}?v=${new Date().getTime()}`;
                document.getElementById("bannerContainer").style.borderBottomColor = nacao.cor_hex !== '#ffffff' ? nacao.cor_hex : '#444';
                document.getElementById("dinLoreNacao").innerHTML = nacao.lore_taticas ? formatarTextoTatico(nacao.lore_taticas) : "<p class='paragraph'>Doutrina militar confidencial.</p>";

                listaTanques.innerHTML = "";
                if (frota.length > 0) {
                    frota.forEach((tanque, index) => {
                        listaTanques.innerHTML += `
                            <a href="${prefixoUrl}ficha.html?id=${tanque.id}" class="tank-card nation-bg">
                                <img src="${prefixoUrl}${tanque.caminho_imagem}?v=${new Date().getTime()}" alt="Silhueta" class="list-silhouette" onerror="this.src='${prefixoUrl}WT - Artes/WT-ICO2.ico'">
                                <div class="tank-info">
                                    <span class="tank-name">${index + 1}. ${tanque.nome}</span>
                                    <span class="tank-desc">${tanque.descricao_breve ? tanque.descricao_breve + '...' : "Pendente."}</span>
                                </div>
                            </a>
                        `;
                    });
                } else {
                    listaTanques.innerHTML = `<div style="text-align: center; padding: 20px; color: #ff4d4d;">Nenhum veículo estacionado nesta base.</div>`;
                }

                if(overlay) overlay.style.display = "none";
                container.style.display = "flex";

                if (perfilLocal === "admin") {
                    if (btnEditarNacao) {
                        btnEditarNacao.style.display = "flex";
                        btnEditarNacao.onclick = () => {
                            document.getElementById("editNacaoId").value = nacaoId;
                            document.getElementById("editNacaoNome").value = nacao.nome;
                            document.getElementById("editNacaoCor").value = nacao.cor_hex;
                            document.getElementById("editNacaoBandeira").value = nacao.caminho_bandeira || "";
                            document.getElementById("editNacaoLore").value = nacao.lore_taticas || "";
                            document.getElementById("formEdicaoNacao").dataset.silhueta = nacao.icone_silhueta || "";
                            document.getElementById("formEdicaoNacao").dataset.resumo = nacao.resumo_card || "";
                            modalNacao.classList.add("ativo");
                        };
                    }
                    if (btnNovoTanque) {
                        btnNovoTanque.style.display = "flex";
                        btnNovoTanque.onclick = async () => {
                            if (confirm("Autorizar início de produção de um novo blindado?")) {
                                btnNovoTanque.innerHTML = "SOLICITANDO..."; btnNovoTanque.disabled = true;
                                try {
                                    let fd = new FormData(); fd.append('acao', 'novo_tanque'); fd.append('nacao_id', nacaoId);
                                    const res = await fetch(`${prefixoUrl}php/api/admin_nacao_api.php`, { method: "POST", body: fd });
                                    const retorno = await res.json();
                                    if (res.ok && retorno.status === "success") window.location.href = `${prefixoUrl}ficha.html?id=${retorno.novo_id}`;
                                    else { alert("Falha: " + retorno.message); btnNovoTanque.innerHTML = "TENTAR NOVAMENTE"; btnNovoTanque.disabled = false; }
                                } catch (err) { btnNovoTanque.disabled = false; }
                            }
                        };
                    }
                }
            } else {
                if(overlay) overlay.innerHTML = `<span style='color:red;'>${json.message}</span>`;
            }
        } catch (err) {
            if(overlay) overlay.innerHTML = "<span style='color:red;'>Falha de conexão.</span>";
        }
    };

    const btnClose = document.getElementById("closeNacaoModal");
    if(btnClose) btnClose.addEventListener("click", () => modalNacao.classList.remove("ativo"));

    higienizarCaminho("editNacaoBandeira");

    const formEdicao = document.getElementById("formEdicaoNacao");
    if (formEdicao) {
        formEdicao.addEventListener("submit", async (e) => {
            e.preventDefault();
            const btnSalvar = document.getElementById("btnSalvarNacao");
            btnSalvar.disabled = true; btnSalvar.innerHTML = "ATUALIZANDO...";
            try {
                let fd = new FormData();
                fd.append("acao", "salvar_nacao");
                fd.append("id", document.getElementById("editNacaoId").value);
                fd.append("nome", document.getElementById("editNacaoNome").value);
                fd.append("cor", document.getElementById("editNacaoCor").value);
                fd.append("bandeira", document.getElementById("editNacaoBandeira").value);
                fd.append("lore", document.getElementById("editNacaoLore").value);
                fd.append("silhueta", document.getElementById("formEdicaoNacao").dataset.silhueta);
                fd.append("resumo", document.getElementById("formEdicaoNacao").dataset.resumo);

                const res = await fetch(`${prefixoUrl}php/api/admin_index_api.php`, { method: "POST", body: fd });
                if (res.ok) window.location.reload();
            } catch (err) {
                btnSalvar.disabled = false; btnSalvar.innerHTML = "ERRO";
            }
        });
    }
    carregarDadosNacao();
}

// ==========================================
// MÓDULO CRUD: DOSSIÊ TÁTICO (FICHA.HTML)
// ==========================================
function iniciarFicha(prefixoUrl) {
    const container = document.getElementById("fichaContainer");
    if (!container) return;

    const urlParams = new URLSearchParams(window.location.search);
    const tankId = urlParams.get('id');
    const overlay = document.getElementById("loadingOverlay");
    const modalEdicao = document.getElementById("edicaoTanqueModal");
    const btnAbrirEdicao = document.getElementById("btnAbrirEdicao");

    let atributosDinamicos = [];
    let galeriaDinamica = [];

    if (!tankId) { if(overlay) overlay.innerHTML = "<span style='color:red;'>ERRO: Blindado não especificado.</span>"; return; }

    const coresClasse = { "Leve": "#FFD700", "Médio": "#FF8C00", "Pesado": "#DC143C", "Caça-Tanques": "#228B22", "SPAA": "#8A2BE2" };
    const nomesClasse = { "Leve": "Tanque Leve", "Médio": "Tanque Médio", "Pesado": "Tanque Pesado", "Caça-Tanques": "Caça-Tanques", "SPAA": "SPAA (Antiaérea)" };

    const carregarFicha = async () => {
        try {
            const resposta = await fetch(`${prefixoUrl}php/api/ficha_api.php?id=${tankId}`);
            const json = await resposta.json();

            if (json.status === "success") {
                const dados = json.dados;
                document.title = `${dados.nome} - Ficha Tática`;
                document.getElementById("dinNomeTanque").textContent = dados.nome;
                
                const classeDoBanco = dados.classe_veiculo || "Médio";
                let textoBadge = nomesClasse[classeDoBanco] || classeDoBanco;
                if (dados.tipo && dados.tipo.trim() !== "") textoBadge += ` (${dados.tipo})`;
                textoBadge += ` | ${dados.nivel || "Nível ?"}`;

                const badge = document.getElementById("dinTipoNivel");
                badge.textContent = textoBadge;
                badge.style.backgroundColor = coresClasse[classeDoBanco] || "#1A3668";
                badge.style.color = classeDoBanco === "Leve" ? "#000000" : "#ffffff";

                document.getElementById("dinHistorico").innerHTML = dados.historico ? formatarTextoTatico(dados.historico) : "<p>Histórico classificado.</p>";
                document.getElementById("dinTaticas").innerHTML = dados.taticas ? formatarTextoTatico(dados.taticas) : "<p>Doutrina em formulação.</p>";

                const corpoTabela = document.getElementById("tabelaEspecificacoesBody");
                if (dados.detalhes_extras && dados.detalhes_extras !== "{}") {
                    try { const parsed = JSON.parse(dados.detalhes_extras); atributosDinamicos = Array.isArray(parsed) ? parsed : Object.entries(parsed).map(([k, v]) => ({ chave: k, valor: v })); } catch (e) {}
                }
                const chavesLegado = [{ chave: "Armamento Principal", valorDB: dados.armamento }, { chave: "Blindagem do Chassi", valorDB: dados.blindagem_chassi }, { chave: "Blindagem da Torre", valorDB: dados.blindagem_torre }, { chave: "Velocidade Máxima", valorDB: dados.velocidade }];
                chavesLegado.forEach(legado => { if (!atributosDinamicos.some(attr => attr.chave === legado.chave) && legado.valorDB) atributosDinamicos.push({ chave: legado.chave, valor: legado.valorDB }); });

                corpoTabela.innerHTML = "";
                atributosDinamicos.forEach(attr => { if (attr.valor.trim() !== "") corpoTabela.insertAdjacentHTML("beforeend", `<tr><th>${attr.chave}</th><td>${attr.valor}</td></tr>`); });

                const track = document.getElementById("tank-track");
                const caption = document.getElementById("tank-caption");
                const btnPrev = document.getElementById("btnPrev");
                const btnNext = document.getElementById("btnNext");

                if (dados.galeria_imagens) { try { galeriaDinamica = JSON.parse(dados.galeria_imagens); } catch (e) {} }

                if (galeriaDinamica.length > 0) {
                    track.innerHTML = "";
                    galeriaDinamica.forEach(img => track.innerHTML += `<img src="${prefixoUrl}${img.url}?v=${new Date().getTime()}" alt="${img.legenda}" class="slide-item">`);
                    caption.textContent = galeriaDinamica[0].legenda || "Visão Oficial em Combate";
                    if (galeriaDinamica.length > 1) {
                        btnPrev.style.display = "block"; btnNext.style.display = "block";
                        let slideAtual = 0;
                        const atualizarSlide = () => { track.style.transform = `translateX(-${100 * slideAtual}%)`; caption.textContent = galeriaDinamica[slideAtual].legenda || ""; };
                        btnNext.onclick = () => { slideAtual = (slideAtual + 1) % galeriaDinamica.length; atualizarSlide(); };
                        btnPrev.onclick = () => { slideAtual = (slideAtual - 1 + galeriaDinamica.length) % galeriaDinamica.length; atualizarSlide(); };
                    }
                } else {
                    const fallbackPath = dados.caminho_imagem.replace("shadow.svg", "foto.webp").replace("shadow.png", "foto.webp");
                    document.getElementById("dinImagemPrincipal").src = `${prefixoUrl}${fallbackPath}?v=${new Date().getTime()}`;
                }

                if(overlay) overlay.style.display = "none";
                container.style.display = "block";

                const perfilLocal = (localStorage.getItem("userRole") || "").toLowerCase();
                if (perfilLocal === "admin" && btnAbrirEdicao) {
                    btnAbrirEdicao.style.display = "flex";
                    btnAbrirEdicao.onclick = () => {
                        document.getElementById("editTankId").value = dados.id;
                        document.getElementById("editNomePrincipal").value = dados.nome || "";
                        document.getElementById("editDescricaoBreve").value = dados.descricao_breve || "";
                        document.getElementById("editCaminhoImagem").value = dados.caminho_imagem || "";
                        document.getElementById("editNomeTitulo").textContent = dados.nome;
                        document.getElementById("editHistorico").value = dados.historico || "";
                        document.getElementById("editTaticas").value = dados.taticas || "";
                        document.getElementById("editClasse").value = dados.classe_veiculo || "Médio";
                        document.getElementById("editFuncao").value = dados.tipo || "";
                        document.getElementById("editNivel").value = dados.nivel || "I";
                        document.getElementById("editNacaoId").value = dados.nacao_id || "1";

                        renderizarListaAtributos(); renderizarListaGaleria();
                        modalEdicao.classList.add("ativo");
                    };
                }
            }
        } catch (err) { if(overlay) overlay.innerHTML = "<span style='color:red;'>FALHA CRÍTICA DE CONEXÃO.</span>"; }
    };

    if (document.getElementById("closeEdicaoModal")) document.getElementById("closeEdicaoModal").onclick = () => modalEdicao.classList.remove("ativo");

    const resetTabs = () => { ["tabFichaLore", "tabGaleria"].forEach(id => { document.getElementById(id).style.background = "#333"; document.getElementById(id).style.color = "#fff"; }); ["painelFichaLore", "painelGaleria"].forEach(id => document.getElementById(id).style.display = "none"); };
    if(document.getElementById("tabFichaLore")) document.getElementById("tabFichaLore").onclick = (e) => { resetTabs(); e.target.style.background = "#F2B400"; e.target.style.color = "#000"; document.getElementById("painelFichaLore").style.display = "block"; };
    if(document.getElementById("tabGaleria")) document.getElementById("tabGaleria").onclick = (e) => { resetTabs(); e.target.style.background = "#F2B400"; e.target.style.color = "#000"; document.getElementById("painelGaleria").style.display = "block"; };

    higienizarCaminho("editCaminhoImagem"); higienizarCaminho("novaFotoCaminho");

    const renderizarListaAtributos = () => {
        const cont = document.getElementById("listaAtributosContainer"); cont.innerHTML = "";
        atributosDinamicos.forEach((attr, index) => {
            cont.insertAdjacentHTML("beforeend", `
                <div class="attr-row">
                    <div style="display:flex; flex-direction:column; gap:2px;"><button type="button" class="btn-move btn-up" data-idx="${index}">▲</button><button type="button" class="btn-move btn-down" data-idx="${index}">▼</button></div>
                    <input type="text" class="input-chave" data-idx="${index}" value="${attr.chave}" style="flex: 1;" placeholder="Atributo">
                    <input type="text" class="input-valor" data-idx="${index}" value="${attr.valor}" style="flex: 2;" placeholder="Valor (Vazio = oculto)">
                    <button type="button" class="btn-del-attr" data-idx="${index}" style="background:var(--rus-vermelho); color:#fff; border:none; padding:8px;">X</button>
                </div>`);
        });
        document.querySelectorAll(".input-chave").forEach(inp => inp.onchange = (e) => atributosDinamicos[e.target.dataset.idx].chave = e.target.value);
        document.querySelectorAll(".input-valor").forEach(inp => inp.onchange = (e) => atributosDinamicos[e.target.dataset.idx].valor = e.target.value);
        document.querySelectorAll(".btn-up").forEach(btn => btn.onclick = (e) => { const idx = parseInt(e.target.dataset.idx); if (idx > 0) { [atributosDinamicos[idx - 1], atributosDinamicos[idx]] = [atributosDinamicos[idx], atributosDinamicos[idx - 1]]; renderizarListaAtributos(); }});
        document.querySelectorAll(".btn-down").forEach(btn => btn.onclick = (e) => { const idx = parseInt(e.target.dataset.idx); if (idx < atributosDinamicos.length - 1) { [atributosDinamicos[idx + 1], atributosDinamicos[idx]] = [atributosDinamicos[idx], atributosDinamicos[idx + 1]]; renderizarListaAtributos(); }});
        document.querySelectorAll(".btn-del-attr").forEach(btn => btn.onclick = (e) => { atributosDinamicos.splice(parseInt(e.target.dataset.idx), 1); renderizarListaAtributos(); });
    };

    if(document.getElementById("btnInjetarTemplate")) document.getElementById("btnInjetarTemplate").onclick = () => {
        ["Armamento Principal", "Blindagem do Chassi", "Blindagem da Torre", "Velocidade Máxima", "Tripulação"].forEach(chave => { if (!atributosDinamicos.some(attr => attr.chave === chave)) atributosDinamicos.push({ chave: chave, valor: "" }); });
        renderizarListaAtributos();
    };

    if(document.getElementById("btnAdicionarAtributo")) document.getElementById("btnAdicionarAtributo").onclick = () => {
        const c = document.getElementById("novoAtributoChave").value.trim(), v = document.getElementById("novoAtributoValor").value.trim();
        if (c) { atributosDinamicos.push({ chave: c, valor: v }); document.getElementById("novoAtributoChave").value = ""; document.getElementById("novoAtributoValor").value = ""; renderizarListaAtributos(); }
    };

    const renderizarListaGaleria = () => {
        const cont = document.getElementById("listaGaleriaContainer"); cont.innerHTML = "";
        galeriaDinamica.forEach((img, idx) => {
            cont.insertAdjacentHTML("beforeend", `<div style="display:flex; justify-content:space-between; align-items:center; background:#222; padding:8px; border:1px solid #444; border-radius:3px;"><div style="font-size:11px; color:#aaa;"><strong style="color:#F2B400;">${img.legenda}</strong><br>${img.url}</div><button type="button" class="btn-del-img" data-index="${idx}" style="background:var(--rus-vermelho); color:#fff; padding:4px 8px; border:none;">X</button></div>`);
        });
        document.querySelectorAll(".btn-del-img").forEach(btn => btn.onclick = (e) => { galeriaDinamica.splice(parseInt(e.target.dataset.index), 1); renderizarListaGaleria(); });
    };

    if(document.getElementById("btnAdicionarFoto")) document.getElementById("btnAdicionarFoto").onclick = () => {
        const url = document.getElementById("novaFotoCaminho").value.trim(), leg = document.getElementById("novaFotoLegenda").value.trim();
        if (url) { galeriaDinamica.push({ url, legenda: leg || "Visão Oficial em Combate" }); document.getElementById("novaFotoCaminho").value = ""; document.getElementById("novaFotoLegenda").value = ""; renderizarListaGaleria(); }
    };

    if(document.getElementById("formEdicaoTanque")) document.getElementById("formEdicaoTanque").onsubmit = async (e) => {
        e.preventDefault();
        const btnSalvar = document.getElementById("btnSalvarDossie"); btnSalvar.disabled = true; btnSalvar.innerHTML = "SALVANDO...";
        try {
            let fd = new FormData();
            fd.append("id", document.getElementById("editTankId").value);
            fd.append("nome", document.getElementById("editNomePrincipal").value);
            fd.append("descricao_breve", document.getElementById("editDescricaoBreve").value);
            fd.append("caminho_imagem", document.getElementById("editCaminhoImagem").value);

            const getValor = (c) => { const f = atributosDinamicos.find(a => a.chave === c); return f ? f.valor : ""; };
            fd.append("armamento", getValor("Armamento Principal")); fd.append("velocidade", getValor("Velocidade Máxima"));
            fd.append("blindagem_chassi", getValor("Blindagem do Chassi")); fd.append("blindagem_torre", getValor("Blindagem da Torre"));

            fd.append("historico", document.getElementById("editHistorico").value);
            fd.append("taticas", document.getElementById("editTaticas").value);
            fd.append("detalhes_extras", JSON.stringify(atributosDinamicos));
            fd.append("galeria_imagens", JSON.stringify(galeriaDinamica));
            fd.append("classe_veiculo", document.getElementById("editClasse").value);
            fd.append("tipo", document.getElementById("editFuncao").value);
            fd.append("nivel", document.getElementById("editNivel").value);
            fd.append("nacao_id", document.getElementById("editNacaoId").value);

            const res = await fetch(`${prefixoUrl}php/api/atualizar_ficha.php`, { method: "POST", body: fd });
            if (res.ok) window.location.reload();
        } catch (err) { btnSalvar.disabled = false; btnSalvar.innerHTML = "ERRO"; }
    };

    const btnExcluir = document.getElementById("btnExcluirDossie");
    if (btnExcluir) btnExcluir.onclick = async () => {
        if (confirm(`ALERTA CRÍTICO: Tem certeza que deseja DELETAR o tanque?`)) {
            btnExcluir.disabled = true; btnExcluir.innerHTML = "INCINERANDO...";
            try {
                let fd = new FormData(); fd.append("id", document.getElementById("editTankId").value);
                const res = await fetch(`${prefixoUrl}php/api/excluir_tanque.php`, { method: "POST", body: fd });
                if (res.ok) window.location.href = `${prefixoUrl}index.html`;
            } catch (err) { btnExcluir.disabled = false; btnExcluir.innerHTML = "ERRO"; }
        }
    };
    carregarFicha();
}

function iniciarScrollSuave() {
    let htmlBotaoTopo = `<button id="btnVoltarTopo" title="Voltar ao Topo"><span class="texto-topo" style="color:#fff; font-weight:bold;">▲ TOPO</span></button>`;
    document.body.insertAdjacentHTML("beforeend", htmlBotaoTopo);
    let btnVoltarTopo = document.getElementById("btnVoltarTopo");
    if (btnVoltarTopo) {
        window.addEventListener("scroll", () => { btnVoltarTopo.classList.toggle("visivel", window.scrollY > 300); });
        btnVoltarTopo.addEventListener("click", () => document.body.scrollIntoView({ behavior: "smooth", block: "start" }));
    }
}

function iniciarToggleVisualizacao(){let e=document.getElementById("btnToggleView"),t=document.querySelector(".nation-content");e&&t&&e.addEventListener("click",()=>{t.classList.toggle("list-view"),t.classList.contains("list-view")?e.innerHTML="&#9638; MODO CAIXAS":e.innerHTML="&#9776; MODO LISTA"})}

function iniciarConfig(){let e=document.getElementById("configModal"),t=document.getElementById("btnOpenConfig"),n=document.getElementById("closeConfigModal"),a=document.getElementById("togglePerf"),o=document.getElementById("themeSelect"),i=document.getElementById("langSelect"),l=document.getElementById("btnPurge");if(!e||!t)return;t.addEventListener("click",t=>{t.preventDefault(),e.classList.add("ativo")}),n.addEventListener("click",()=>e.classList.remove("ativo")),"true"===localStorage.getItem("lowPerf")&&(a.checked=!0,document.body.classList.add("low-perf")),a.addEventListener("change",e=>{e.target.checked?(localStorage.setItem("lowPerf","true"),document.body.classList.add("low-perf")):(localStorage.setItem("lowPerf","false"),document.body.classList.remove("low-perf"))});let s=localStorage.getItem("siteTheme")||"dark";o.value=s,"desert"===s&&document.body.classList.add("theme-desert"),"night"===s&&document.body.classList.add("theme-night"),o.addEventListener("change",e=>{document.body.classList.remove("theme-desert","theme-night"),"desert"===e.target.value&&document.body.classList.add("theme-desert"),"night"===e.target.value&&document.body.classList.add("theme-night"),localStorage.setItem("siteTheme",e.target.value)});let d=localStorage.getItem("siteLang")||"pt";i.value=d,i.addEventListener("change",e=>{localStorage.setItem("siteLang",e.target.value);let t=document.getElementById("customBanner");t&&(document.getElementById("customBannerText").textContent="Idioma salvo. Atualize a página.",document.getElementById("bannerIcon").innerHTML="language",t.classList.add("show"),setTimeout(()=>t.classList.remove("show"),4e3))}),l.addEventListener("click",()=>{localStorage.clear(),location.reload()})}

// ==========================================
// FUNÇÃO MESTRA: INICIALIZADOR GLOBAL
// ==========================================
function injetarMenu(prefixoUrl) {
    document.addEventListener("DOMContentLoaded", () => {
        injetarInterface(prefixoUrl);
        iniciarLogin(prefixoUrl);
        iniciarRegistro(prefixoUrl);
        iniciarRecuperacaoSenha(prefixoUrl);
        iniciarConfig();
        iniciarRelogio();
        ativarRadarPesquisa(prefixoUrl);
        ativarAbaTatica(); // Aba do Menu ativada!
        iniciarScrollSuave();
        iniciarToggleVisualizacao();
        iniciarTropas(prefixoUrl);
        
        iniciarIndex(prefixoUrl);
        iniciarNacao(prefixoUrl);
        iniciarFicha(prefixoUrl);

        document.addEventListener("click", evento => {
            let btnToggle = document.getElementById("navToggleBtn");
            let barraMenu = document.querySelector(".top-navbar");
            if (btnToggle && barraMenu) {
                if (btnToggle.contains(evento.target)) barraMenu.classList.toggle("expanded");
                else if (!barraMenu.contains(evento.target)) barraMenu.classList.remove("expanded");
            }
            
            const badge = document.getElementById("userNationBadge");
            const dropdown = document.getElementById("userNationDropdown");
            if (badge && dropdown) {
                if (badge.contains(evento.target)) dropdown.style.display = dropdown.style.display === "block" ? "none" : "block";
                else dropdown.style.display = "none";
            }
        });
        
        const dropdownOpts = document.querySelectorAll(".nation-opt");
        if(dropdownOpts) dropdownOpts.forEach(opt => {
            opt.addEventListener("click", async (e) => {
                e.stopPropagation();
                const nacaoEscolhida = opt.getAttribute("data-nation");
                try {
                    let formData = new FormData(); formData.append("acao", "salvar_nacao"); formData.append("nacao", nacaoEscolhida);
                    const res = await fetch(`${prefixoUrl}php/api/usuarios.php`, { method: "POST", body: formData });
                    const json = await res.json();
                    if (res.ok && json.status === "success") {
                        localStorage.setItem("userNation", nacaoEscolhida);
                        renderizarPlacaNacaoTopo(nacaoEscolhida);
                        document.getElementById("userNationDropdown").style.display = "none";
                    }
                } catch (err) { }
            });
        });
    });
}